def transform(grid):
    h, w = len(grid), len(grid[0])
    # The marks are diagonal color clues. Extend their diagonal stripes into
    # a periodic diagonal pattern; use the colors in their order of appearance
    # along the diagonal coordinate.
    bands = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                bands.setdefault(c - r, v)

    offsets = sorted(bands)
    colors = []
    for k in offsets:
        if bands[k] not in colors:
            colors.append(bands[k])

    # Repeated colors in the clues represent repeated entries in the cycle.
    if len(colors) == 1:
        return [[colors[0] for _ in range(w)] for _ in range(h)]

    # Align the cycle to preserve the clues wherever possible.
    period = len(colors)
    anchor = offsets[0]
    anchor_color = bands[anchor]
    cycle = colors[colors.index(anchor_color):] + colors[:colors.index(anchor_color)]
    return [[cycle[(c-r-anchor) % period] for c in range(w)] for r in range(h)]
